import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { AuthService } from '../../core/services/auth/auth.services';
import { ChecklistService } from '../../core/services/checklist/checklist.service';
import { NoteService } from '../../core/services/note/note.service';
import { ScheduleService } from '../../core/services/schedule/schedule.service';
import { StudyService } from '../../core/services/study/study.service';

@Component({
    selector: 'app-dashboard',
    standalone: true,
    imports: [CommonModule, FormsModule],
    templateUrl: './dashboard.component.html',
    styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
    private authService = inject(AuthService);
    private checklistService = inject(ChecklistService);
    private noteService = inject(NoteService);
    private scheduleService = inject(ScheduleService);
    private studyService = inject(StudyService);

    profileData = {
        name: '',
        email: '',
        password: ''
    };
    isSavingProfile = false;

    newTaskTitle = '';
    newTaskDate = '2026-07-02';

    newNoteTitle = '';
    newNoteContent = '';

    newScheduleTitle = '';
    newScheduleDescription = '';
    newScheduleDate = '2026-07-02';
    newScheduleType = 'Diário';

    newGoalCategory = '';
    newGoalMinutes = 30;

    newSessionSubject = '';
    newSessionMinutes = 45;

    tasks: any[] = [];
    notes: any[] = [];
    schedules: any[] = [];
    goals: any[] = [];
    sessionHistory: any[] = [];

    metrics: any = {
        completedTasks: 0,
        pendingTasks: 0,
        studyHours: 0
    };

    ngOnInit(): void {
        this.loadTasks();
        this.loadNotes();
        this.loadSchedules();
        this.loadGoals();
        this.loadSessionHistory();
        this.loadDashboardMetrics();

        const savedUser = localStorage.getItem('currentUser');
        if (savedUser) {
            const user = JSON.parse(savedUser);
            this.profileData.name = user.name || user.nome || '';
            this.profileData.email = user.email || '';
        }
    }

    loadTasks(): void {
        this.checklistService.getTasksByUser().subscribe({
            next: (res) => {
                this.tasks = Array.isArray(res) ? res : [];
            },
            error: (err) => {
                console.error(err);
                this.tasks = [];
            }
        });
    }

    loadNotes(): void {
        this.noteService.getNotesByUser().subscribe({
            next: (res) => {
                this.notes = Array.isArray(res) ? res : [];
            },
            error: (err) => {
                console.error(err);
                this.notes = [];
            }
        });
    }

    loadSchedules(): void {
        this.scheduleService.getSchedulesByUser().subscribe({
            next: (res) => {
                this.schedules = Array.isArray(res) ? res : [];
            },
            error: (err) => {
                console.error(err);
                this.schedules = [];
            }
        });
    }

    loadGoals(): void {
        this.studyService.getGoals().subscribe({
            next: (res) => {
                this.goals = Array.isArray(res) ? res : [];
            },
            error: (err) => {
                console.error(err);
                this.goals = [];
            }
        });
    }

    loadSessionHistory(): void {
        this.studyService.getSessionHistory().subscribe({
            next: (res) => {
                this.sessionHistory = Array.isArray(res) ? res : [];
            },
            error: (err) => {
                console.error(err);
                this.sessionHistory = [];
            }
        });
    }

    loadDashboardMetrics(): void {
        this.studyService.getStudyDashboard().subscribe({
            next: (res) => {
                if (res && !Array.isArray(res)) {
                    this.metrics = {
                        completedTasks: res.completedTasks || 0,
                        pendingTasks: res.pendingTasks || 0,
                        studyHours: res.studyHours || 0
                    };
                }
            },
            error: (err) => console.error(err)
        });
    }

    submitProfileUpdate(): void {
        if (!this.profileData.name || !this.profileData.email || !this.profileData.password) {
            alert('Por favor, preencha todos os campos, incluindo a confirmação da senha.');
            return;
        }

        this.isSavingProfile = true;
        this.authService.updateProfile(this.profileData).subscribe({
            next: (res) => {
                this.isSavingProfile = false;
                alert('Perfil atualizado com sucesso! Por segurança, faça login novamente se alterou seu e-mail.');
                this.profileData.password = '';
            },
            error: (err) => {
                this.isSavingProfile = false;
                console.error(err);
                alert('Falha ao atualizar dados. Verifique os critérios dos campos.');
            }
        });
    }

    addTask(): void {
        if (!this.newTaskTitle) return;
        this.checklistService.createTask({ title: this.newTaskTitle, date: this.newTaskDate }).subscribe({
            next: () => {
                this.newTaskTitle = '';
                this.loadTasks();
                this.loadDashboardMetrics();
            },
            error: (err) => console.error(err)
        });
    }

    toggleTask(task: any): void {
        this.checklistService.toggleTask(task.id).subscribe({
            next: () => {
                this.loadTasks();
                this.loadDashboardMetrics();
            },
            error: (err) => console.error(err)
        });
    }

    deleteTask(id: number): void {
        this.checklistService.deleteTask(id).subscribe({
            next: () => {
                this.loadTasks();
                this.loadDashboardMetrics();
            },
            error: (err) => console.error(err)
        });
    }

    addNote(): void {
        if (!this.newNoteTitle || !this.newNoteContent) return;
        this.noteService.createNote({ title: this.newNoteTitle, content: this.newNoteContent }).subscribe({
            next: () => {
                this.newNoteTitle = '';
                this.newNoteContent = '';
                this.loadNotes();
            },
            error: (err) => console.error(err)
        });
    }

    deleteNote(id: number): void {
        this.noteService.deleteNote(id).subscribe({
            next: () => this.loadNotes(),
            error: (err) => console.error(err)
        });
    }

    addSchedule(): void {
        if (!this.newScheduleTitle) return;
        const payload = {
            title: this.newScheduleTitle,
            description: this.newScheduleDescription,
            eventDate: this.newScheduleDate,
            typeSchedule: this.newScheduleType
        };
        this.scheduleService.createSchedule(payload).subscribe({
            next: () => {
                this.newScheduleTitle = '';
                this.newScheduleDescription = '';
                this.loadSchedules();
            },
            error: (err) => console.error(err)
        });
    }

    deleteSchedule(id: number): void {
        this.scheduleService.deleteSchedule(id).subscribe({
            next: () => this.loadSchedules(),
            error: (err) => console.error(err)
        });
    }

    addGoal(): void {
        if (!this.newGoalCategory) return;
        this.studyService.saveGoal({ category: this.newGoalCategory, targetMinutes: this.newGoalMinutes }).subscribe({
            next: () => {
                this.newGoalCategory = '';
                this.loadGoals();
            },
            error: (err) => console.error(err)
        });
    }

    addSession(): void {
        if (!this.newSessionSubject) return;
        this.studyService.registerSession({ subject: this.newSessionSubject, durationMinutes: this.newSessionMinutes }).subscribe({
            next: () => {
                this.newSessionSubject = '';
                this.loadSessionHistory();
                this.loadDashboardMetrics();
            },
            error: (err) => console.error(err)
        });
    }
}
